function Invoke-ProSoakPhase($Session,[string]$Phase,$Guard,[string]$ProNonce,[long]$ArchiveMaxBytes=0){
 $meta=$Guard.ReadCommand('soak-inputs.json')|ConvertFrom-Json
 if($meta.format -ne 1 -or $meta.proNonce -ne $ProNonce -or $meta.caseId -notmatch '^[a-f0-9]{32}$' -or $meta.appCase -notmatch '^[a-f0-9]{32}$' -or $meta.supportCase -notmatch '^[a-f0-9]{32}$' -or $meta.zipSha256 -notmatch '^[a-f0-9]{64}$'){throw 'Bound soak fixture required'}
 if($Phase -in @('soak-stage','soak-stage-finish')){
  $Guard.PinInputFile([string]$meta.zip);if((Get-FileHash -LiteralPath $meta.zip).Hash.ToLowerInvariant() -ne $meta.zipSha256){throw 'Soak archive changed'}
  Invoke-Command -Session $Session -ScriptBlock {if((Get-Service vmms).Status -ne 'Running' -or @(Get-VM).Count){throw 'Ready empty Pro required'}}
  $archive='C:\MuLab\private\soak-'+$meta.caseId+'.zip';if($Phase -eq 'soak-stage'){Copy-Item -LiteralPath $meta.zip -Destination $archive -ToSession $Session}
  return Invoke-Command -Session $Session -ArgumentList $meta,$archive,($Phase -eq 'soak-stage-finish') -ScriptBlock {
   param($meta,$archive,$finish)
   $ErrorActionPreference='Stop';$tools='C:\MuLab\soak-tools\'+$meta.caseId
   if($meta.packagedApp){$app=Join-Path $tools 'app'}else{$app='C:\MuLab\exchange-tools\'+$meta.appCase+'\app';$previous=[IO.File]::ReadAllText(('C:\MuLab\approved\exchange-'+$meta.appCase+'-result.json'))|ConvertFrom-Json;if(-not $previous.complete -or -not $previous.processExitConfirmed -or -not $previous.brokerExitConfirmed -or -not $previous.nested.removed){throw 'Completed unchanged preview app required'}}
   if((Test-Path -LiteralPath $tools) -ne $finish){throw 'Soak staging state requires inspection'}
   $configFile='C:\MuLab\approved\soak-'+$meta.caseId+'-config.json';$emptyConfig=$false
   if(Test-Path $configFile){$entry=Get-Item -LiteralPath $configFile;if(-not $finish -or $entry.PSIsContainer -or $entry.Length -ne 0 -or ($entry.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Existing soak config requires inspection'};$emptyConfig=$true}
   if((Test-Path ('C:\MuLab\public\soak-'+$meta.caseId+'-owner.json')) -or (Get-ScheduledTask -TaskName ('MuPro-soak-'+$meta.caseId) -ErrorAction SilentlyContinue)){throw 'Only unused unfinished soak staging may finish'}
   foreach($folder in @('C:\','C:\MuLab','C:\MuLab\soak-tools')){if((Test-Path -LiteralPath $folder) -and ((Get-Item -LiteralPath $folder).Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Soak staging reparse directory refused'}}
   $expected='C:\MuLab\image-tools\'+$meta.supportCase;$support=[IO.File]::ReadAllText(('C:\MuLab\approved\image-'+$meta.supportCase+'-config.json'))|ConvertFrom-Json;$node=Join-Path $expected 'product/resources/node/node.exe'
   if($support.caseId -ne $meta.supportCase -or $support.tools -ne $expected -or $support.image -ne ('C:\MuLab\images\image-'+$meta.supportCase+'.vhdx') -or $support.imageSha256 -ne $meta.imageSha256 -or (Get-FileHash -LiteralPath $support.image).Hash.ToLowerInvariant() -ne $meta.imageSha256 -or (Get-FileHash -LiteralPath $node).Hash.ToLowerInvariant() -ne $meta.nodeSha256 -or (Get-FileHash -LiteralPath $archive).Hash.ToLowerInvariant() -ne $meta.zipSha256){throw 'Soak base/runtime/archive changed'}
   Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=[IO.Compression.ZipFile]::OpenRead($archive)
   try{[long]$bytes=0;if($zip.Entries.Count -gt 12000){throw 'Excessive soak entries'};foreach($entry in $zip.Entries){$name=$entry.FullName.Replace('\','/');$bytes+=$entry.Length;if($bytes -gt 2GB -or $entry.Length -gt 128MB -or $name.Contains(':') -or $name.StartsWith('/') -or @($name.Split('/')|Where-Object{$_ -in @('.','..')}).Count -or (-not $name.StartsWith('app/') -and $name -notin @('pro-soak-client.mjs','pro-soak-stream.py','local-fixtures.mjs','fixture-key.pem','fixture-cert.pem'))){throw 'Unsafe soak archive'}}}finally{$zip.Dispose()}
   if(-not $finish){[IO.Compression.ZipFile]::ExtractToDirectory($archive,$tools)};if((Get-Item -LiteralPath $tools).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Soak tools reparse directory refused'};foreach($entry in $meta.files.psobject.Properties){if((Get-FileHash -LiteralPath (Join-Path $tools $entry.Name)).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Soak fixture changed'}}
   foreach($entry in $meta.artifacts.psobject.Properties){if((Get-FileHash -LiteralPath (Join-Path $app $entry.Name)).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Soak program changed'}}
   $config=@{caseId=$meta.caseId;proNonce=$meta.proNonce;version=$meta.version;tools=$tools;app=$app;support=$expected;node=$node;nodeSha256=$meta.nodeSha256;image=$support.image;imageSha256=$support.imageSha256;files=$meta.files;artifacts=$meta.artifacts;sourceDigest=$meta.sourceDigest;userSid=(Get-LocalUser MuLabUser).SID.Value}
   if($emptyConfig){if((Get-Item -LiteralPath $configFile).Length -ne 0){throw 'Unfinished soak config changed'};[IO.File]::Move($configFile,($configFile+'.empty-'+[guid]::NewGuid().ToString('N')))}
   $file='C:\MuLab\approved\soak-'+$meta.caseId+'-config.json';$stream=[IO.File]::Open($file,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$configBytes=[Text.UTF8Encoding]::new($false).GetBytes(($config|ConvertTo-Json -Depth 8));$stream.Write($configBytes,0,$configBytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};return @{complete=$true;staged=$true;caseId=$meta.caseId;desktopBaseReused=$true}
  }
 }
 return Invoke-Command -Session $Session -ArgumentList $meta.caseId,$Phase,$ArchiveMaxBytes -ScriptBlock {
  param($caseId,$phase,$archiveMaxBytes)
  $ErrorActionPreference='Stop';$prefix='C:\MuLab\public\soak-'+$caseId;$approved='C:\MuLab\approved\soak-'+$caseId;$cfg=[IO.File]::ReadAllText($approved+'-config.json')|ConvertFrom-Json
  if($cfg.caseId -ne $caseId -or $cfg.tools -ne ('C:\MuLab\soak-tools\'+$caseId)){throw 'Soak identity changed'}
  if($phase -in @('soak-preserve','soak-preserve-finish')){
   $finish=$phase -eq 'soak-preserve-finish'
   $result=[IO.File]::ReadAllText($approved+'-result.json')|ConvertFrom-Json;$id=[string]$result.nested.id;$vm=Get-VM -Id ([guid]$result.nested.platformId)
   if($id -cne ([guid]$id).ToString('D') -or $result.caseId -ne $caseId -or $result.complete -ne $false -or -not $result.processExitConfirmed -or -not $result.brokerExitConfirmed -or -not $result.nested.confirmedOff -or $result.nested.removed -or $vm.Name -ne ('mu-win-'+$id.Replace('-','')) -or [string]$vm.State -ne 'Off' -or @(Get-CimInstance Win32_Process|Where-Object{($_.ExecutablePath -eq $cfg.node -and $_.CommandLine -like ('*'+$caseId+'*')) -or $_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-*.exe'}).Count){throw 'Exact stopped terminal soak required for preservation'}
   $root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$cfg.userSid);$ledger=[IO.File]::ReadAllText((Join-Path $root 'vms.json'))|ConvertFrom-Json;$disk=Join-Path $root ('vms/'+$id+'/disk.vhdx');$drives=@(Get-VMHardDiskDrive -VM $vm);$archive='C:\MuLab\private\soak-'+$caseId+'-failed-original'
   if($ledger.ownerSid -ne $cfg.userSid -or $ledger.records.$id.ownerSid -ne $cfg.userSid -or $ledger.records.$id.platformId -ne [string]$vm.Id -or $drives.Count -ne 1 -or [IO.Path]::GetFullPath($drives[0].Path) -ne $disk -or ((Test-Path $archive) -ne $finish) -or (Test-Path (Join-Path $archive 'preserved.json'))){throw 'Original registered disk/archive boundary changed'}
   $vhd=Get-VHD -Path $disk;$length=(Get-Item -LiteralPath $disk).Length;if($vhd.ParentPath -or $vhd.Attached -or $length -gt $archiveMaxBytes -or [IO.DriveInfo]::new('C:\').AvailableFreeSpace -lt ($length+8GB)){throw 'Standalone stopped disk and bounded storage headroom required'}
   foreach($path in @('C:\','C:\MuLab','C:\MuLab\private')){if((Get-Item -LiteralPath $path -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Preservation parent reparse refused'}};[IO.Directory]::CreateDirectory($archive)|Out-Null;if((Get-Item -LiteralPath $archive -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Preservation archive reparse refused'}
   $hashes=@{};$pin=[IO.File]::Open($disk,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
   try{$before=(Get-FileHash $disk).Hash.ToLowerInvariant();if(-not $finish){$out=[IO.File]::Open((Join-Path $archive 'disk.vhdx'),[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$pin.CopyTo($out,1048576);$out.Flush($true)}finally{$out.Dispose()}};if((Get-FileHash (Join-Path $archive 'disk.vhdx')).Hash.ToLowerInvariant() -ne $before -or (Get-FileHash $disk).Hash.ToLowerInvariant() -ne $before){throw 'Preserved original disk did not match'};$hashes['disk.vhdx']=$before}finally{$pin.Dispose()}
   $runtime=$prefix+'-runtime\'+$vm.Name;$copies=@{}
   foreach($name in @('management','management.pub','host-ed25519','host-ed25519.pub','known_hosts','manifest.json','allocation.json','seed.iso')){$copies['runtime-'+$name]=Join-Path $runtime $name}
   foreach($name in @('state.sqlite','credentials.dpapi','state.sqlite-wal','state.sqlite-shm')){$copies['workspace-'+$name]=Join-Path ($prefix+'-app') $name}
   foreach($name in @('vms.json','vms.backup.json')){$copies['protected-'+$name]=Join-Path $root $name}
   foreach($name in @('config','result','offline')){$copies['approved-'+$name+'.json']=$approved+'-'+$name+'.json'}
   foreach($entry in @(Get-ChildItem -LiteralPath 'C:\MuLab\approved' -Filter ('soak-'+$caseId+'-offline-*.json') -File)){$copies[$entry.Name]=$entry.FullName}
   foreach($name in $copies.Keys){$source=[IO.Path]::GetFullPath($copies[$name]);$target=[IO.Path]::GetFullPath((Join-Path $archive $name));if([IO.Path]::GetDirectoryName($target) -ne $archive -or -not $source.StartsWith('C:\MuLab\',[StringComparison]::OrdinalIgnoreCase) -and -not $source.StartsWith($root+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Preservation file path escaped its fixture'};if(-not(Test-Path -LiteralPath $source)){if($name -in @('workspace-state.sqlite-wal','workspace-state.sqlite-shm')){continue};throw ('Required preservation metadata missing: '+$name)};$path=$source;while($path){if((Get-Item -LiteralPath $path -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Preservation metadata reparse refused'};$path=[IO.Path]::GetDirectoryName($path)};$hash=(Get-FileHash -LiteralPath $source).Hash.ToLowerInvariant();if(Test-Path -LiteralPath $target){if(-not $finish){throw 'Existing metadata preserved'}}else{[IO.File]::Copy($source,$target,$false)};if((Get-FileHash -LiteralPath $target).Hash.ToLowerInvariant() -ne $hash -or (Get-FileHash -LiteralPath $source).Hash.ToLowerInvariant() -ne $hash){throw 'Preserved metadata changed'};$hashes[$name]=$hash}
   $proof=@{complete=$true;caseId=$caseId;originalId=$id;platformId=[string]$vm.Id;diskIdentifier=[string]$vhd.DiskIdentifier;archive=$archive;hashes=$hashes;sourceUnchanged=$true;originalResourcesRetained=$true;scope='private synthetic diagnostic archive; not a product backup'};[IO.File]::WriteAllText((Join-Path $archive 'preserved.json'),($proof|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText($approved+'-preserved.json',($proof|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false));return $proof
  }
  if($phase -eq 'soak-diagnostics'){
   $result=[IO.File]::ReadAllText($approved+'-result.json')|ConvertFrom-Json
   if($result.caseId -ne $caseId -or -not $result.processExitConfirmed -or -not $result.brokerExitConfirmed){throw 'Terminal owner-bound soak receipt required'}
   $root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$cfg.userSid);$trips=@{}
   foreach($name in @('power-trip.json','resource-trip.json','channel-errors.log')){$file=Join-Path $root $name;if(Test-Path -LiteralPath $file){$stream=[IO.File]::Open($file,[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete));try{if($stream.Length -gt 8000){$stream.Position=$stream.Length-8000};$reader=[IO.StreamReader]::new($stream);$trips[$name]=$reader.ReadToEnd()}finally{$stream.Dispose()}}}
   $db=$prefix+'-app\state.sqlite';$before=(Get-FileHash -LiteralPath $db).Hash.ToLowerInvariant();$program="import{DatabaseSync}from'node:sqlite';const db=new DatabaseSync(process.argv[1],{readOnly:true});const raw=JSON.parse(db.prepare('SELECT config FROM environments').get().config);const value={logs:db.prepare('SELECT id,level,message,created_at FROM logs ORDER BY id DESC LIMIT 60').all(),environment:{state:raw.state,lastError:raw.lastError}};console.log(Buffer.from(JSON.stringify(value)).toString('base64'));db.close();"
   $text=& $cfg.node --no-warnings --input-type=module -e $program $db;if($LASTEXITCODE -ne 0){throw 'Read-only fixture log query failed'};$after=(Get-FileHash -LiteralPath $db).Hash.ToLowerInvariant();if($after -ne $before){throw 'Read-only fixture database changed'}
   $start=([DateTime]::Parse($result.startedAt)).ToUniversalTime();$events=@(Get-WinEvent -FilterHashtable @{LogName='System';StartTime=$start;EndTime=[DateTime]::UtcNow} -ErrorAction SilentlyContinue|Where-Object{$_.ProviderName -match 'Hyper-V|Kernel-Power|Resource-Exhaustion|Time-Service'}|Select-Object TimeCreated,ProviderName,Id,LevelDisplayName)
   return @{complete=$true;caseId=$caseId;originalResultPreserved=$true;databaseUnchanged=$true;product=([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String([string]$text))|ConvertFrom-Json);nativeTrips=$trips;systemEvents=$events}
  }
  if($phase -eq 'soak-cancel'){
   if(Test-Path ($prefix+'-result.json')){throw 'Terminal soak result must be inspected'}
   $owner=[IO.File]::ReadAllText($prefix+'-owner.json')|ConvertFrom-Json;$progress=[IO.File]::ReadAllText($prefix+'-progress.json')|ConvertFrom-Json;$actor=Get-CimInstance Win32_Process -Filter ('ProcessId='+[int]$owner.pid)
   if($progress.caseId -ne $caseId -or $progress.pid -ne $owner.pid -or $progress.nonce -cne $owner.nonce -or $actor.ExecutablePath -ne $cfg.node -or $actor.CommandLine -notlike ('*pro-soak-client.mjs*'+$caseId+'*') -or (Invoke-CimMethod -InputObject $actor -MethodName GetOwnerSid).Sid -ne $cfg.userSid){throw 'Actual soak owner required for cancellation'}
   $root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$cfg.userSid);$ledger=[IO.File]::ReadAllText((Join-Path $root 'vms.json'))|ConvertFrom-Json;$id=[string]$progress.nested.id;$record=$ledger.records.$id;$vm=Get-VM -Id ([guid]$progress.nested.platformId);$expectedName='mu-win-'+$id.Replace('-','');$disks=@(Get-VMHardDiskDrive -VM $vm)
   if($ledger.ownerSid -ne $cfg.userSid -or $record.ownerSid -ne $cfg.userSid -or $record.platformId -ne [string]$vm.Id -or $vm.Name -ne $expectedName -or $vm.Notes -ne ('MuCodeSandbox Windows preview '+$expectedName) -or $disks.Count -ne 1 -or [IO.Path]::GetFullPath($disks[0].Path) -ne (Join-Path $root ('vms/'+$id+'/disk.vhdx'))){throw 'Exact registered soak VM required'}
   Stop-VM -VM $vm -TurnOff -Force;if((Get-VM -Id $vm.Id).State -ne 'Off'){throw 'Soak cancellation stop unconfirmed'}
   return @{complete=$true;caseId=$caseId;cancelRequested=$true;originalDiskPreserved=$true;platformId=[string]$vm.Id}
  }
  if($phase -eq 'soak-inspect'){
   $tcp=@{observed=$false;states=@();nonLoopback=0};$controllers=@(Get-CimInstance Win32_Process|Where-Object{$_.ExecutablePath -eq $cfg.node -and $_.CommandLine -like ('*pro-soak-client.mjs*'+$caseId+'*')});if($controllers.Count -eq 1 -and (Invoke-CimMethod -InputObject $controllers[0] -MethodName GetOwnerSid).Sid -eq $cfg.userSid){$connections=@(Get-NetTCPConnection -OwningProcess $controllers[0].ProcessId -ErrorAction SilentlyContinue);$tcp=@{observed=$true;ownerPid=$controllers[0].ProcessId;states=@($connections|Group-Object State|ForEach-Object{@{state=[string]$_.Name;count=$_.Count}});nonLoopback=@($connections|Where-Object{$_.RemoteAddress -notin @('127.0.0.1','::1','0.0.0.0','::')}).Count}}
   $reports=@();foreach($kind in @('progress','result')){if(Test-Path ($prefix+'-'+$kind+'.json')){$reports+=[IO.File]::ReadAllText($prefix+'-'+$kind+'.json')|ConvertFrom-Json}}
   $logs=@();foreach($file in @(($prefix+'-client.log'),($approved+'-broker-error.log'))){if(Test-Path $file){$stream=[IO.File]::Open($file,[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete));try{if($stream.Length -gt 5000){$stream.Position=$stream.Length-5000};$reader=[IO.StreamReader]::new($stream);$logs+=@{name=[IO.Path]::GetFileName($file);tail=$reader.ReadToEnd()}}finally{$stream.Dispose()}}}
   $archive='C:\MuLab\private\soak-'+$caseId+'-failed-original';$archiveState=@{present=(Test-Path -LiteralPath $archive);diskBytes=0;complete=(Test-Path -LiteralPath (Join-Path $archive 'preserved.json'))};if(Test-Path -LiteralPath (Join-Path $archive 'disk.vhdx')){$archiveState.diskBytes=(Get-Item -LiteralPath (Join-Path $archive 'disk.vhdx')).Length}
   $hashes=@{};foreach($entry in $cfg.artifacts.psobject.Properties){$hashes[$entry.Name]=(Get-FileHash (Join-Path $cfg.app $entry.Name)).Hash.ToLowerInvariant()};$nested=@(Get-VM|ForEach-Object{@{id=[string]$_.Id;name=$_.Name;state=[string]$_.State}})
   $root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$cfg.userSid);$ledger=[IO.File]::ReadAllText((Join-Path $root 'vms.json'))|ConvertFrom-Json
   return @{complete=$true;caseId=$caseId;version=$cfg.version;reports=$reports;logs=$logs;artifactHashes=$hashes;clientSha256=(Get-FileHash (Join-Path $cfg.tools 'pro-soak-client.mjs')).Hash.ToLowerInvariant();actors=@(Get-CimInstance Win32_Process|Where-Object{($_.ExecutablePath -eq $cfg.node -and $_.CommandLine -like ('*'+$caseId+'*')) -or $_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-*.exe'}|Select-Object ProcessId,ExecutablePath,CommandLine);nested=$nested;tcp=$tcp;archive=$archiveState;registeredGuests=@($ledger.records.psobject.Properties).Count;runtimeDirectories=@(Get-ChildItem -LiteralPath (Join-Path $root 'vms') -Force).Count;registrationCopiesEqual=((Get-FileHash (Join-Path $root 'vms.json')).Hash -eq (Get-FileHash (Join-Path $root 'vms.backup.json')).Hash);sourceDigest=$cfg.sourceDigest}
  }
  if($phase -ne 'soak-run' -or @(Get-VM).Count -or (Get-Service vmms).Status -ne 'Running'){throw 'Ready empty Pro required for soak run'}
  $task='MuPro-soak-'+$caseId;$ownerFile=$prefix+'-owner.json';$resultFile=$prefix+'-result.json';if((Test-Path $ownerFile) -or (Test-Path $resultFile) -or (Get-ScheduledTask -TaskName $task -ErrorAction SilentlyContinue)){throw 'Existing soak work must be inspected'}
  $script=Join-Path $cfg.tools 'pro-soak-client.mjs';foreach($entry in $cfg.files.psobject.Properties){if((Get-FileHash (Join-Path $cfg.tools $entry.Name)).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Soak inputs changed'}};if((Get-FileHash $cfg.node).Hash.ToLowerInvariant() -ne $cfg.nodeSha256){throw 'Soak Node changed'}
  $launch='$env:PSModulePath=Join-Path $PSHOME ''Modules''; & '''+$cfg.node+''' --no-warnings '''+$script+''' '+$caseId+' *> '''+$prefix+'-client.log'';exit $LASTEXITCODE';$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($launch));$principal=New-ScheduledTaskPrincipal -UserId 'MU-PRO-LAB\MuLabUser' -LogonType Interactive -RunLevel Limited;$action=New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot 'System32/WindowsPowerShell/v1.0/powershell.exe') -Argument ('-NoProfile -NonInteractive -WindowStyle Hidden -EncodedCommand '+$encoded) -WorkingDirectory C:\MuLab\public;$settings=New-ScheduledTaskSettingsSet -ExecutionTimeLimit ([TimeSpan]::FromHours(1)) -MultipleInstances IgnoreNew;Register-ScheduledTask -TaskName $task -Action $action -Principal $principal -Settings $settings|Out-Null;Start-ScheduledTask -TaskName $task
  $until=[DateTime]::UtcNow.AddMinutes(3);while(-not(Test-Path $ownerFile)){if([DateTime]::UtcNow -gt $until){throw 'Soak owner not observed; retain task for inspection'};Start-Sleep -Milliseconds 200};$owner=[IO.File]::ReadAllText($ownerFile)|ConvertFrom-Json;$actor=Get-CimInstance Win32_Process -Filter ('ProcessId='+[int]$owner.pid);if($owner.caseId -ne $caseId -or $owner.nonce -notmatch '^[a-f0-9]{64}$' -or $actor.ExecutablePath -ne $cfg.node -or $actor.CommandLine -notlike ('*'+$script+'*'+$caseId+'*') -or (Invoke-CimMethod -InputObject $actor -MethodName GetOwnerSid).Sid -ne $cfg.userSid){throw 'Soak controller identity changed'}
  $handle=Get-Process -Id $owner.pid;$null=$handle.Handle;$bin=Join-Path $env:ProgramData 'MuCodeSandbox-HyperVBroker-v1/bin';$artifact=[IO.File]::ReadAllText((Join-Path $bin 'current.json'))|ConvertFrom-Json;$broker=Join-Path $bin $artifact.brokerFile;if($artifact.sourceDigest -ne $cfg.sourceDigest -or (Get-FileHash $broker).Hash.ToLowerInvariant() -ne $artifact.brokerSha256){throw 'Soak protected broker changed'}
  $agent=Start-Process -FilePath $broker -ArgumentList @('--owner',[string]$owner.pid,'--pipe',[string]$owner.nonce,'--detect-host') -WorkingDirectory $bin -WindowStyle Hidden -RedirectStandardOutput ($approved+'-broker-out.log') -RedirectStandardError ($approved+'-broker-error.log') -PassThru;$null=$agent.Handle;$until=[DateTime]::UtcNow.AddMinutes(55)
  do{if(Test-Path $resultFile){if(-not $handle.WaitForExit(15000) -or -not $agent.WaitForExit(45000)){throw 'Soak controller or broker remains live'};$result=[IO.File]::ReadAllText($resultFile)|ConvertFrom-Json;if($result.caseId -ne $caseId -or $result.pid -ne $owner.pid -or $result.nonce -cne $owner.nonce){throw 'Soak result identity changed'};$result|Add-Member -NotePropertyName processExitConfirmed -NotePropertyValue $true;$result|Add-Member -NotePropertyName brokerExitConfirmed -NotePropertyValue $true;[IO.File]::WriteAllText($approved+'-result.json',($result|ConvertTo-Json -Depth 16),[Text.UTF8Encoding]::new($false));Unregister-ScheduledTask -TaskName $task -Confirm:$false;return $result};if($handle.HasExited){throw 'Soak controller exited without receipt; retain resources'};if([DateTime]::UtcNow -gt $until){throw 'Soak run remains unconfirmed; inspect live handles'};Start-Sleep -Milliseconds 200}while($true)
 }
}
